
#include "dsalib/input_parser.h"
#include <algorithm>
#include <sstream>
namespace dsalib {
InputParser::InputParser():off_(0),version_(0){} InputParser::InputParser(const std::vector<unsigned char>& bytes){reset(bytes);} void InputParser::reset(const std::vector<unsigned char>& bytes){data_=bytes;off_=0;version_=0;parse_header();} uint32_t InputParser::version() const{return version_;} bool InputParser::eof() const{return off_>=data_.size()-4;}
void InputParser::require(size_t n) const{ if(off_+n>data_.size()) throw std::runtime_error("dsalib input truncated"); }
uint8_t InputParser::read_byte(){require(1);return data_[off_++];} uint32_t InputParser::read_u32(){require(4);uint32_t v=0;for(int i=0;i<4;++i)v|=((uint32_t)data_[off_++])<<(8*i);return v;}
void InputParser::parse_header(){ if(data_.size()<12) throw std::runtime_error("short dsalib stream"); if(data_[0]!='D'||data_[1]!='S'||data_[2]!='A'||data_[3]!='1') throw std::runtime_error("bad magic"); off_=4; version_=read_u32(); if(version_!=1) throw std::runtime_error("unsupported version"); uint32_t stored=data_.size()>=4?((uint32_t)data_[data_.size()-4]|((uint32_t)data_[data_.size()-3]<<8)|((uint32_t)data_[data_.size()-2]<<16)|((uint32_t)data_[data_.size()-1]<<24)):0; uint32_t actual=checksum(data_,0,data_.size()-4); if(stored!=actual) throw std::runtime_error("checksum mismatch"); }
uint64_t InputParser::read_varuint(){uint64_t value=0;int shift=0;while(true){uint8_t b=read_byte();value|=(uint64_t)(b&0x7f)<<shift;if(!(b&0x80))break;shift+=7;if(shift>63)throw std::runtime_error("varuint overflow");}return value;} int64_t InputParser::read_varint(){uint64_t z=read_varuint();return (int64_t)((z>>1)^-(int64_t)(z&1));}
void InputParser::expect_type(uint8_t type){uint8_t got=read_byte();if(got!=type)throw std::runtime_error("unexpected record type");}
std::vector<int> InputParser::parse_array(){expect_type(TYPE_ARRAY);uint64_t n=read_varuint();std::vector<int>a;for(uint64_t i=0;i<n;++i)a.push_back((int)read_varint());return a;}
LinkedList<int> InputParser::parse_linked_list(){expect_type(TYPE_LIST);uint64_t n=read_varuint();LinkedList<int> l;for(uint64_t i=0;i<n;++i)l.push_back((int)read_varint());return l;}
Graph InputParser::parse_graph(){expect_type(TYPE_GRAPH);int n=(int)read_varuint();bool dir=read_byte()!=0;int m=(int)read_varuint();Graph g(n,dir);for(int i=0;i<m;++i){int u=(int)read_varuint();int v=(int)read_varuint();int w=(int)read_varint();g.add_edge(u,v,w);}return g;}
TreeNode<int>* InputParser::parse_tree(){expect_type(TYPE_TREE);std::function<TreeNode<int>*()> rec=[&](){uint8_t present=read_byte();if(!present)return (TreeNode<int>*)NULL;TreeNode<int>* n=new TreeNode<int>((int)read_varint());n->left=rec();n->right=rec();return n;};return rec();}
BinaryField InputParser::parse_nested(){expect_type(TYPE_NESTED);BinaryField f;f.type=read_byte();uint64_t payload=read_varuint();for(uint64_t i=0;i<payload;++i)f.payload.push_back(read_byte());uint64_t kids=read_varuint();for(uint64_t i=0;i<kids;++i)f.children.push_back(parse_nested());return f;}
void InputParser::append_varuint(std::vector<unsigned char>& out,uint64_t value){while(value>=0x80){out.push_back((unsigned char)(value|0x80));value>>=7;}out.push_back((unsigned char)value);} void InputParser::append_varint(std::vector<unsigned char>& out,int64_t value){uint64_t z=((uint64_t)value<<1)^(uint64_t)(value>>63);append_varuint(out,z);} uint32_t InputParser::checksum(const std::vector<unsigned char>& bytes,size_t begin,size_t end){uint32_t h=2166136261u;for(size_t i=begin;i<end;++i){h^=bytes[i];h*=16777619u;}return h;}
void InputParser::append_u32(std::vector<unsigned char>& out,uint32_t v){for(int i=0;i<4;++i)out.push_back((unsigned char)((v>>(8*i))&255));} void InputParser::finish(std::vector<unsigned char>& out){uint32_t c=checksum(out,0,out.size());append_u32(out,c);} 
std::vector<unsigned char> InputParser::encode_array(const std::vector<int>& a){std::vector<unsigned char>o;o.push_back('D');o.push_back('S');o.push_back('A');o.push_back('1');append_u32(o,1);o.push_back(TYPE_ARRAY);append_varuint(o,a.size());for(size_t i=0;i<a.size();++i)append_varint(o,a[i]);finish(o);return o;}
std::vector<unsigned char> InputParser::encode_linked_list(const std::vector<int>& a){std::vector<unsigned char>o;o.push_back('D');o.push_back('S');o.push_back('A');o.push_back('1');append_u32(o,1);o.push_back(TYPE_LIST);append_varuint(o,a.size());for(size_t i=0;i<a.size();++i)append_varint(o,a[i]);finish(o);return o;}
std::vector<unsigned char> InputParser::encode_graph(const Graph& g){std::vector<unsigned char>o;o.push_back('D');o.push_back('S');o.push_back('A');o.push_back('1');append_u32(o,1);o.push_back(TYPE_GRAPH);append_varuint(o,g.size());o.push_back(g.directed()?1:0);int m=0;for(int u=0;u<g.size();++u)m+=g.neighbors(u).size();append_varuint(o,m);for(int u=0;u<g.size();++u){const std::vector<std::pair<int,int> >& ns=g.neighbors(u);for(size_t i=0;i<ns.size();++i){append_varuint(o,u);append_varuint(o,ns[i].first);append_varint(o,ns[i].second);}}finish(o);return o;}
void InputParser::encode_tree_node(std::vector<unsigned char>& out,TreeNode<int>* root){if(!root){out.push_back(0);return;}out.push_back(1);append_varint(out,root->data);encode_tree_node(out,root->left);encode_tree_node(out,root->right);} std::vector<unsigned char> InputParser::encode_tree(TreeNode<int>* root){std::vector<unsigned char>o;o.push_back('D');o.push_back('S');o.push_back('A');o.push_back('1');append_u32(o,1);o.push_back(TYPE_TREE);encode_tree_node(o,root);finish(o);return o;}
}
